META = json.loads('{"genreShuffle": {"placeholders": {"label": {"type": "String"}, "n": {"type": "int"}}}, "regionBrandLine": {"placeholders": {"n": {"type": "int"}}}}')


def load(p):
    if not os.path.exists(p):
        print(f'❌ {p} 파일이 없어요. 프로젝트 폴더(C:\\apps\\mp3_player_new)에서 실행해 주세요.'); sys.exit(1)
    raw = open(p, 'rb').read().decode('utf-8')
    return raw.replace('\r\n', '\n'), '\r\n' in raw


def main():
    texts, crlf = {}, {}
    for k, p in list(FILES.items()) + [('arb_' + l, p) for l, p in ARBF.items()]:
        texts[k], crlf[k] = load(p)
    if '"genreSortedToast"' in texts['arb_ko'] and '_IntroText.fromTr()' in texts['pi']:
        print('이미 적용돼 있어요'); return

    ok = True
    # 코드 고치기
    for f, name, old, new in EDITS:
        n = texts[f].count(old)
        if n == 1:
            texts[f] = texts[f].replace(old, new)
            print(f'✔ {os.path.basename(FILES[f])} - {name}')
        else:
            print(f'❌ {os.path.basename(FILES[f])} - {name} (찾을 코드가 {n}군데)'); ok = False

    # 번역 파일에 새 글자 넣기 (맨 끝 } 앞에)
    for l, p in ARBF.items():
        k = 'arb_' + l
        t = texts[k]
        try:
            have = json.loads(t)
        except Exception as e:
            print(f'❌ {os.path.basename(p)} - 번역 파일을 못 읽었어요 ({e})'); ok = False; continue
        dup = [x for x in ARB[l] if x in have]
        if dup:
            print(f'❌ {os.path.basename(p)} - 이미 있는 이름: {", ".join(dup[:5])}'); ok = False; continue
        lines = [f'  {json.dumps(x, ensure_ascii=False)}: {json.dumps(v, ensure_ascii=False)}' for x, v in ARB[l].items()]
        if l == 'ko':  # 기준 파일에만 {n} 같은 자리 설명
            lines += [f'  {json.dumps("@" + x)}: {json.dumps(v, ensure_ascii=False)}' for x, v in META.items()]
        end = t.rstrip().rfind('}')
        body = t[:end].rstrip()
        t2 = body + ',\n' + ',\n'.join(lines) + '\n' + t[end:]
        try:
            d = json.loads(t2)
            assert all(d[x] == v for x, v in ARB[l].items())
        except Exception as e:
            print(f'❌ {os.path.basename(p)} - 넣은 뒤 번역 파일이 깨져요 ({e})'); ok = False; continue
        texts[k] = t2
        print(f'✔ {os.path.basename(p)} - 새 글자 {len(ARB[l])}개')

    if not ok:
        print('\n❌ 못 찾은 곳이 있어서 아무것도 저장하지 않았어요.'); sys.exit(1)

    for k, p in list(FILES.items()) + [('arb_' + l, p) for l, p in ARBF.items()]:
        t = texts[k].replace('\n', '\r\n') if crlf[k] else texts[k]
        open(p, 'wb').write(t.encode('utf-8'))
    print('\n완료! 이제 flutter gen-l10n 후 flutter run 해 주세요.')


main()
